-- =============================================================================
-- CivicBrain | seed/seed_synthetic_demo_data.sql
-- OPTIONAL demo data for an EMPTY database built with V1 -> V4:
--   1 synthetic user, the 500 synthetic Step 8 complaints (is_synthetic = true, wards already
--   re-derived by V3), 109 Step 12 duplicate relations, and the Step 13 prototype tables.
-- Do NOT run on the database restored from civicbrain_backup (it already has this data).
-- Run as a SUPERUSER (postgres): session_replication_role=replica switches off triggers and
-- foreign-key checks while loading, so no notifications/jobs are created for demo rows and the
-- self-referencing duplicate links load in any order.
-- NOTE (problem 1 in the gap analysis): step13_* rows were built from a different CSV version of
-- the complaints; re-run Step 13 on this data before presenting those results.
-- =============================================================================
BEGIN;
SET LOCAL session_replication_role = replica;
SET LOCAL search_path = public;
